const $=s=>document.querySelector(s),{localDate,parseNote,escapeHTML:esc,validRecord}=KotoCore;
let db,state={profile:null,records:[]},pendingPhoto='',editingId=null,editorImage='',step=0,answers={},recognition=null;
const questions=[{key:'name',title:'なんと呼びましょうか？',type:'text',placeholder:'ニックネーム（あとでも大丈夫）'},{key:'goal',title:'どんな自分に近づきたいですか？',options:['体重を減らしたい','体調を整えたい','食生活を知りたい','まだ決めていない']},{key:'method',title:'どんな記録なら続けられそう？',options:['声と写真で','声を中心に','写真を中心に','文字入力で']},{key:'weight',title:'今の体重を教えてください。',type:'number',placeholder:'kg・あとで記録しても大丈夫',detail:'最初の記録の基準に使います。目標体重の設定は必須ではありません。'},{key:'care',title:'記録に残しておきたい配慮はありますか？',type:'text',placeholder:'食事制限、アレルギー、医療者からの指示など',detail:'この版ではメモとして保存します。自動的な食事・医療判断には使いません。'},{key:'tone',title:'どんな声かけが好きですか？',options:['優しく励ましてほしい','端的にはっきり伝えてほしい','小さな変化を一緒に喜びたい']}];
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
async function init(){try{db=await new Promise((resolve,reject)=>{const req=indexedDB.open('kotolog',1);req.onupgradeneeded=()=>req.result.createObjectStore('journal');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});const saved=await new Promise((resolve,reject)=>{const req=db.transaction('journal').objectStore('journal').get('state');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});if(saved)state=saved;render();}catch(e){toast('保存領域が利用できません。別のブラウザーで開いてください。');$('#organize').disabled=true;$('#start').disabled=true;}}
function persist(next){return new Promise((resolve,reject)=>{const tx=db.transaction('journal','readwrite');tx.objectStore('journal').put(next,'state');tx.oncomplete=()=>{state=next;resolve();};tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
function drawQuestion(){const q=questions[step];$('#stepCount').textContent=`あなたに合う続け方 · ${step+1} / ${questions.length}`;$('#question').textContent=q.title;$('#back').disabled=step===0;$('#onboardingForm button[type=submit]').textContent=step===questions.length-1?'記録をはじめる →':'次へ →';$('#questionBody').innerHTML=q.options?q.options.map(o=>`<label class="option"><input type="radio" name="answer" value="${esc(o)}" ${answers[q.key]===o?'checked':''}>${esc(o)}</label>`).join(''):`${q.detail?`<p>${esc(q.detail)}</p>`:''}<input aria-label="${esc(q.title)}" id="answer" type="${q.type}" ${q.type==='number'?'min="1" max="500" step="0.1"':''} placeholder="${esc(q.placeholder)}" value="${esc(answers[q.key]||'')}">`;}
async function advance(skip=false){const q=questions[step];if(!skip)answers[q.key]=q.options?$('#questionBody input:checked')?.value||'':$('#answer').value;if(step<questions.length-1){step++;drawQuestion();return;}const next={...state,profile:{...answers}};try{await persist(next);$('#onboarding').close();render();toast('準備ができました。今日のひとことから始めましょう。');$('#note').focus();}catch(e){toast('保存できませんでした。空き容量を確認してください。');}}
$('#start').onclick=$('#settings').onclick=()=>{answers={...(state.profile||{})};step=0;drawQuestion();$('#onboarding').showModal();};$('#onboardingForm').onsubmit=e=>{e.preventDefault();advance();};$('#skip').onclick=()=>advance(true);$('#back').onclick=()=>{step--;drawQuestion();};$('#closeOnboarding').onclick=()=>$('#onboarding').close();
$('#today').textContent=new Date().toLocaleDateString('ja-JP',{month:'long',day:'numeric',weekday:'short'});
$('#speak').onclick=()=>{const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('このブラウザーは音声認識に対応していません。メモ欄で端末の音声入力を使えます。');$('#note').focus();return;}if(recognition){recognition.stop();return;}try{recognition=new Speech();recognition.lang='ja-JP';recognition.interimResults=true;recognition.continuous=false;const original=$('#note').value;$('#speak strong').textContent='聞いています…';$('#voiceStatus').textContent='もう一度押すと終了します。話し終わったら内容を確認してください。';recognition.onresult=e=>{let text='';for(let i=0;i<e.results.length;i++)text+=e.results[i][0].transcript;$('#note').value=original+(original?'\n':'')+text;};recognition.onerror=e=>toast(e.error==='not-allowed'?'マイクの利用が許可されていません。端末の音声入力も使えます。':'音声を受け取れませんでした。もう一度お試しください。');recognition.onend=()=>{recognition=null;$('#speak strong').textContent='話して記録';$('#voiceStatus').textContent='話した内容を確認し、「記録を確認」で保存してください。';};recognition.start();}catch(e){recognition=null;$('#speak strong').textContent='話して記録';toast('音声入力を開始できませんでした。端末の音声入力をご利用ください。');}};
$('#photoButton').onclick=()=>$('#photo').click();$('#photo').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>25*1024*1024){toast('25MB以下の写真を選んでください。');return;}try{pendingPhoto=await compress(file);$('#photoPreview').src=pendingPhoto;$('#photoPreview').hidden=false;$('#removePhoto').hidden=false;toast('写真を用意しました。食事や量をひとこと添えられます。');}catch(e){toast('写真を読み込めませんでした。JPEG・PNGでお試しください。');}};
function compress(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onerror=()=>{URL.revokeObjectURL(url);reject();};img.onload=()=>{try{const scale=Math.min(1,1200/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.8));}catch(e){reject(e);}finally{URL.revokeObjectURL(url);}};img.src=url;});}
$('#removePhoto').onclick=()=>{pendingPhoto='';$('#photoPreview').hidden=true;$('#removePhoto').hidden=true;$('#photo').value='';};
function openEditor(entry=null){if(recognition)recognition.stop();editingId=entry?.id||null;const r=entry||parseNote($('#note').value);editorImage=entry?entry.photo||'':pendingPhoto;const f=$('#entryForm');for(const key of ['date','kind','weight','sleep','feeling','easy','note'])f.elements[key].value=r[key]??'';$('#editorPhoto').hidden=!editorImage;if(editorImage)$('#editorPhoto').src=editorImage;$('#editor h2').textContent=entry?'記録を編集':'記録を確認';$('#editor').showModal();}
$('#organize').onclick=()=>{if(!$('#note').value.trim()&&!pendingPhoto){toast('ひとこと話すか、写真を選んでください。');return;}openEditor();};$('#cancelEdit').onclick=()=>$('#editor').close();
$('#entryForm').onsubmit=async e=>{e.preventDefault();const f=e.target,entry={id:editingId||crypto.randomUUID(),date:f.elements.date.value,kind:f.elements.kind.value,weight:f.elements.weight.value===''?'':Number(f.elements.weight.value),sleep:f.elements.sleep.value===''?'':Number(f.elements.sleep.value),feeling:f.elements.feeling.value,easy:f.elements.easy.value,note:f.elements.note.value,photo:editorImage,updatedAt:new Date().toISOString()};if(!validRecord(entry)){toast('日付と数値を確認してください。');return;}const list=state.records.filter(r=>r.id!==entry.id);list.push(entry);const btn=f.querySelector('[type=submit]');btn.disabled=true;try{await persist({...state,records:list});$('#editor').close();if(!editingId){$('#note').value='';$('#removePhoto').click();}render();toast('記録を保存しました。');}catch(e){toast('保存できませんでした。バックアップ後に空き容量を確認してください。');}finally{btn.disabled=false;}};
function sorted(){return [...state.records].sort((a,b)=>a.date.localeCompare(b.date)||a.updatedAt.localeCompare(b.updatedAt));}
function render(){const list=sorted(),weighted=list.filter(r=>r.weight!==''),last=weighted.at(-1),days=new Set(list.map(r=>r.date)).size;$('#welcome').hidden=!!state.profile;const baseline=Number(state.profile?.weight)||weighted[0]?.weight;$('#summary').innerHTML=`<div class="stat"><span>最近の体重</span><strong>${last?esc(last.weight)+' <small>kg</small>':'—'}</strong></div><div class="stat"><span>最初の記録から</span><strong>${last&&baseline?(last.weight-baseline>0?'+':'')+(last.weight-baseline).toFixed(1)+' <small>kg</small>':'—'}</strong></div><div class="stat"><span>記録した日</span><strong>${days} <small>日</small></strong></div>`;$('#count').textContent=`${list.length}件`;$('#records').innerHTML=list.length?[...list].reverse().map(r=>`<article class="record"><div class="record-top"><strong>${esc(r.date)} · ${esc(r.kind)}</strong><div class="record-actions"><button data-edit="${esc(r.id)}">編集</button><button data-delete="${esc(r.id)}">削除</button></div></div>${r.note?`<p>${esc(r.note)}</p>`:''}${r.photo?`<img alt="食事の記録写真" loading="lazy" src="${r.photo}">`:''}<div class="chips">${r.weight!==''?`<span>体重 ${esc(r.weight)}kg</span>`:''}${r.sleep!==''?`<span>睡眠 ${esc(r.sleep)}時間</span>`:''}${r.feeling?`<span>体調 ${esc(r.feeling)}</span>`:''}${r.easy?`<span>${esc(r.easy)}</span>`:''}</div></article>`).join(''):'<div class="empty">まだ記録はありません。<br>今日のひとことが、最初の一歩です。</div>';drawChart();reflect();}
$('#records').onclick=async e=>{const edit=e.target.dataset.edit,del=e.target.dataset.delete;if(edit)openEditor(state.records.find(r=>r.id===edit));if(del&&confirm('この記録と写真を削除しますか？')){try{await persist({...state,records:state.records.filter(r=>r.id!==del)});render();toast('削除しました。');}catch(e){toast('削除できませんでした。');}}};
$('#period').onchange=drawChart;
function drawChart(){const period=$('#period').value,cutoff=new Date();cutoff.setDate(cutoff.getDate()-Number(period)+1);const start=localDate(cutoff),daily=new Map();sorted().filter(r=>r.weight!==''&&(period==='all'||r.date>=start)).forEach(r=>daily.set(r.date,r.weight));const points=[...daily.entries()];if(points.length<2){$('#chart').textContent=points.length?'体重をもう一日記録すると、変化が見えます。':'体重を記録すると、ここに変化が見えます。';return;}const vals=points.map(p=>p[1]),lo=Math.min(...vals)-.3,hi=Math.max(...vals)+.3,first=new Date(points[0][0]+'T12:00:00').getTime(),end=new Date(points.at(-1)[0]+'T12:00:00').getTime();const xy=points.map(([d,v])=>[50+(new Date(d+'T12:00:00').getTime()-first)/(end-first)*470,145-(v-lo)/(hi-lo)*115]);$('#chart').innerHTML=`<svg viewBox="0 0 560 180" role="img" aria-label="体重の推移。${esc(points.map(([d,v])=>d+' '+v+'kg').join('、'))}"><line x1="50" y1="145" x2="520" y2="145" stroke="#dae1d3"/><line x1="50" y1="30" x2="520" y2="30" stroke="#eef0e9"/><text x="0" y="38" fill="#7c8974" font-size="12">${hi.toFixed(1)}</text><text x="0" y="145" fill="#7c8974" font-size="12">${lo.toFixed(1)}</text><polyline fill="none" stroke="#648773" stroke-width="3" points="${xy.map(p=>p.join(',')).join(' ')}"/>${xy.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#648773"><title>${points[i][0]} ${points[i][1]}kg</title></circle>`).join('')}<text x="50" y="172" fill="#7c8974" font-size="12">${points[0][0].slice(5)}</text><text x="480" y="172" fill="#7c8974" font-size="12">${points.at(-1)[0].slice(5)}</text></svg>`;}
function reflect(){const start=new Date();start.setDate(start.getDate()-6);const recent=sorted().filter(r=>r.date>=localDate(start)&&r.date<=localDate()),days=new Set(recent.map(r=>r.date)).size,sleeps=recent.filter(r=>r.sleep!==''),easy=recent.filter(r=>r.easy==='続けやすかった');const name=state.profile?.name?esc(state.profile.name)+'さん、':'',tone=state.profile?.tone;let lead=days?`${name}この7日間に${days}日、記録を残しました。`:'今日から、また始められます。';if(tone==='小さな変化を一緒に喜びたい'&&days)lead=`${name}${days}日分の「自分を知る手がかり」が増えました。`;$('#reflection').innerHTML=`<strong>この7日間の振り返り</strong>${lead}${sleeps.length?` 記録した睡眠の平均は${(sleeps.reduce((a,r)=>a+r.sleep,0)/sleeps.length).toFixed(1)}時間です（${sleeps.length}件）。`:''}${easy.length?` 「続けやすかった」が${easy.length}件ありました。その日の記録を振り返ってみましょう。`:''}<br>${tone==='端的にはっきり伝えてほしい'?'次の一歩：':'次は、'}${recent.some(r=>r.photo)?'写真に、食べた量のひとことを添えてみましょう。':'明日の記録に「続けやすかったか」を一つ残してみましょう。'}<br><small>未記録の食事や体調は、判断に含めません。</small>`;}
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`kotolog-backup-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('写真を含むバックアップを作成しました。');};$('#importButton').onclick=()=>$('#import').click();$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100*1024*1024)throw new Error();const imported=JSON.parse(await f.text());if(imported.version!==1||!Array.isArray(imported.records)||!imported.records.every(validRecord)||imported.records.some(r=>typeof r.updatedAt!=='string')||!(imported.profile===null||typeof imported.profile==='object'))throw new Error();if(!confirm('バックアップの記録を追加します。同じIDの記録はバックアップの内容で更新します。続けますか？'))return;const map=new Map(state.records.map(r=>[r.id,r]));imported.records.forEach(r=>map.set(r.id,r));await persist({profile:state.profile||imported.profile,records:[...map.values()]});render();toast('バックアップを読み込みました。');}catch(e){toast('読み込めませんでした。ことログのバックアップと空き容量を確認してください。');}finally{e.target.value='';}};
init();
